from pathlib import Path
import json
from collections import Counter

lines = Path('/root/schema_semantic_constrained_ie/outputs/ee_mistral_wikievents_constrained_v2_full.jsonl').read_text().strip().split('\n')
records = [json.loads(l) for l in lines]

ont = json.loads(Path('/root/schema_semantic_constrained_ie/data/wikievents/ontology_constraints_wikievents.json').read_text())
valid_event_types = set(ont['event_types'])
valid_entity_types = set(ont['entity_types'])
event_constraints = ont.get('event_constraints', {})

arg_constraints = {}
for et, ec in event_constraints.items():
    arg_constraints[et] = ec.get('role_entity_constraints', {})

valid_roles_map = {}
for et, ec in event_constraints.items():
    valid_roles_map[et] = set(ec.get('valid_roles', []))

def norm_et(raw, valid):
    t = raw.strip()
    if t in valid:
        return t
    tn = t.lower().replace(' ', '').replace('_', '').replace('-', '')
    for vt in valid:
        vn = vt.lower().replace(' ', '').replace('_', '').replace('-', '')
        if tn == vn:
            return vt
    return None

def norm_enty(raw, valid):
    t = raw.strip()
    if t in valid:
        return t
    tu = t.upper()
    for vt in valid:
        if tu == vt.upper():
            return vt
    return None

ac_by_predicted_type = Counter()
ac_by_role = Counter()
total_by_ent_type = Counter()

for rec in records:
    po = rec.get('parsed_output')
    if po is None:
        continue
    events = po.get('events', [])
    for evt in events:
        raw_et = evt.get('event_type', '')
        net = norm_et(raw_et, valid_event_types)
        if net is None:
            continue
        args = evt.get('arguments', [])
        vr = valid_roles_map.get(net, set())
        ac = arg_constraints.get(net, {})
        for arg in args:
            role = arg.get('role', '')
            ent_type = arg.get('entity_type', '')
            total_by_ent_type[ent_type] += 1
            if role in vr:
                net_ent = norm_enty(ent_type, valid_entity_types)
                allowed_types = set(ac.get(role, []))
                if allowed_types:
                    actual_check = net_ent not in allowed_types if net_ent else True
                    if actual_check:
                        ac_by_predicted_type[ent_type] += 1
                        ac_by_role[role] += 1

print('AC violations by predicted entity_type (top 15):')
for t, c in ac_by_predicted_type.most_common(15):
    print(f'  {t}: {c}')
print()
print('AC violations by role (top 15):')
for r, c in ac_by_role.most_common(15):
    print(f'  {r}: {c}')
print()
print('Entity type distribution in args (top 15):')
for t, c in total_by_ent_type.most_common(15):
    print(f'  {t}: {c}')
"
